const r=GPT.flashData();for(let i=0;i<r.q.length;i++){const a=Transformer.attention([r.q[i]],r.k.slice(0,i+1),r.v.slice(0,i+1))[0];a.forEach((v,j)=>{if(Math.abs(v-GPT_DATA.reference.prefixes[i][j])>1e-9)throw Error('prefix');});}
for(const c of GPT_DATA.reference.cache)if(Transformer.cacheBytes(c.layers,c.heads,c.width,c.length)!==c.bytes)throw Error('bytes');
for(const h of [1,2,8])for(let q=0;q<8;q++)if(Transformer.group(q,8,h)!==Math.floor(q/(8/h)))throw Error('group');for(let stage=1;stage<=5;stage++){const cached=GPT.cacheCounts(stage,true),full=GPT.cacheCounts(stage,false);if(cached.total!==stage+3||full.total!==stage*4+stage*(stage-1)/2)throw Error('count');}return 'all causal prefixes, nine byte counts and all head mappings';

