for(const mode of ['full','cache']){set('cache-mode',mode);document.getElementById('cache-reset').click();for(let stage=1;stage<=5;stage++)document.getElementById('cache-next').click();if(!document.getElementById('cache-next').disabled)throw Error('cache end');}
for(const h of [1,2,8]){set('gqa-heads',h);for(const n of [1,1024,8192])set('gqa-length',n);}
for(const mask of ['full','causal'])for(const tile of [1,2,3])for(let q=0;q<5;q++){set('flash-mask',mask);set('flash-tile',tile);set('flash-query',q);document.getElementById('flash-reset').click();for(let s=0;s<6&&!document.getElementById('flash-next').disabled;s++)document.getElementById('flash-next').click();if(!document.getElementById('flash-next').disabled)throw Error('tile end');}set('flash-mode','naive');if(!document.getElementById('flash-next').disabled)throw Error('naive');set('flash-mode','tiles');GPT.flashStep=1;GPT.cacheStage=2;redrawAll();return 'prefill/decode, 3 KV layouts, 30 tiled states and naive mode';
